    "t30": "འཚོལ་ཞིབ་ཡོ་བྱད་མཐུད་རྗེས། དུམ་བུ་དང་། ཉོ་ཚོང་བརྗེ་རེས། དྲ་རྒྱའི་བྱ་འགུལ་བཅས་འཚོལ་ཞིབ་བྱེད་ས།",
