    "t32": "གསར་སྤེལ་བའི་འགྲོ་ལམ་དེ་འཕྲིན་གཏོང་གྲོས་མཐུན་རྟོགས་པ་ནས་འགོ་འཛུགས། ཡོ་བྱད་རིམ་བཞིན་འབྱོར་སྐབས། མཐུད་སྦྱོར་དང་ཉེར་སྤྱོད་ལ་སྐྱོད།",
    "t33": "དྲ་རྒྱའི་ནང་གི་ཁྱེད་ཀྱི་གནས།",
    "t34": "རང་གི་ལམ་འཚོལ།<br><em>གོམ་པ་རྗེས་མ་སྤོ།</em>",
    "t35": "དངུལ་ཁུག་སྤྱོད།",
    "t36": "PoCol མ་ལག་ཏུ་འཇུག་པའི་སྒོ།",
    "t37": "དྲ་རྒྱར་ཞུགས།",
    "t38": "མཐུད་ཚིགས་དང་གཏེར་འདོན་ངོ་ཤེས།",
    "t39": "PoCol དང་མཉམ་དུ་སྐྲུན།",
    "t40": "འཕྲིན་གཏོང་གྲོས་མཐུན་ནས་འགོ་འཛུགས།",
    "t41": "མདུན་གྱི་འགྲོ་ལམ།",
    "t42": "འཕེལ་བཞིན་པའི་འདུ་ཤེས།<br>གོམ་པ་རེ་རེ་བཞིན།",
    "t43": "རྨང་གཞི།",
    "t44": "འཕྲིན་གཏོང་གྲོས་མཐུན་དང་ཞིབ་འཇུག",
    "t45": "མཉམ་ལས་ཀྱི་ལས་འགྲོའི་ཐབས་ལམ་དང་དེའི་ཞིབ་འཇུག་རྨང་གཞི།",
    "t46": "ཉམས་མྱོང་།",
    "t47": "དྲ་རྒྱ་དང་ཡོ་བྱད།",
    "t48": "དངུལ་ཁུག་དང་། མཉམ་ཞུགས། བྱ་འགུལ་འཚོལ་ཞིབ།",
    "t49": "མ་འོངས་པའི་རྒྱང་ལྟ།",
    "t50": "འཕེལ་བཞིན་པའི་མ་ལག",
    "t51": "ཞུགས་མཁན་རྣམས་ཀྱི་ཆེད་དུ་ཡོ་བྱད་དང་ཉེར་སྤྱོད་གསར་སྤེལ།",
    "t52": "འཕེལ་ཕྱོགས་ཀྱི་སྤྱི་བསྡོམས་ཡིན། འཆར་གཞི་གཏན་འཁེལ་རྗེས། ལག་བསྟར་གྱི་དུས་མཚམས་དང་ཚེས་གྲངས་ཁྱབ་བསྒྲགས་བྱ་རྒྱུ་ཡིན།",
    "t53": "མ་འོངས་པ།<br><em>མཉམ་དུ་སྐྲུན།</em>",
