    "walletBody": "ཉེར་སྤྱོད་ཀྱི་པར་གཞི་དག་དྲ་ཚིགས་འདིར་འགྲེམ་སྤེལ་བྱེད་ཆོག་པའི་ཆོག་མཆན་ཐོབ་རྗེས། གཞུང་འབྲེལ་གྱི་ཕབ་ལེན་སྦྲེལ་ཐག་དང་དངུལ་ཁུག་སྒྲིག་འཛུགས་ལམ་སྟོན་ཁ་སྣོན་བྱ་རྒྱུ་ཡིན། འདི་ནི་དྲ་ཚིགས་ཇུས་འགོད་ཀྱི་སྔོན་ལྟ་ཞིག་ཡིན།",
    "nodeTitle": "དྲ་རྒྱར་ཞུགས།",
    "nodeBody": "ལམ་འདིར་མཐུད་ཚིགས་ཀྱི་དགོས་མཁོ་དང་། དྲ་རྒྱའི་སྒྲིག་འགོད། གཏེར་འདོན་ནང་ཞུགས་ཚུལ་བཅས་འཁོད་རྒྱུ་ཡིན། ཞིབ་བཤེར་བྱས་པའི་སྒྲིག་འཛུགས་ལམ་སྟོན་གྲ་སྒྲིག་ཟིན་རྗེས་འདིར་ཁྱབ་བསྒྲགས་བྱ་རྒྱུ་ཡིན།",
    "devTitle": "གསར་སྤེལ་བ་རྣམས་ལ།",
    "devBody": "དྲ་ཚིགས་དང་མཐུད་རྗེས། སྡེ་ཚན་འདིར་ཞིབ་བཤེར་བྱས་པའི་འཕྲིན་གཏོང་གྲོས་མཐུན་ཡིག་ཆ་དང་། མཐུད་སྦྱོར་འབྲེལ་ངོས། དཔེ་མཚོན་བཅས་འཁོད་རྒྱུ་ཡིན།",
