    "t26": "Proof of Collaboration ដាក់ការសម្របសម្រួលជាចំណុចស្នូលនៃគំនិត៖ តើអ្នកចូលរួមអាចធ្វើការរួមគ្នាក្នុងបណ្តាញតែមួយបានយ៉ាងដូចម្តេច?",
