    "t30": "កន្លែងសម្រាប់ស្វែងរកប្លុក ប្រតិបត្តិការ និងសកម្មភាពបណ្តាញ នៅពេលកម្មវិធីរុករកត្រូវបានតភ្ជាប់។",
