    "t42": "ແນວຄິດທີ່ພັດທະນາ<br>ເທື່ອລະກ້າວ",
    "t43": "ຮາກຖານ",
    "t44": "ໂປຣໂຕຄອນ ແລະການຄົ້ນຄວ້າ",
    "t45": "ກົນໄກການຮ່ວມມື ແລະຮາກຖານການຄົ້ນຄວ້າ.",
    "t46": "ປະສົບການ",
    "t47": "ເຄືອຂ່າຍ ແລະເຄື່ອງມື",
    "t48": "ກະເປົາເງິນ, ການມີສ່ວນຮ່ວມ ແລະການສຳຫຼວດກິດຈະກຳ.",
    "t49": "ຂອບຟ້າ",
    "t50": "ລະບົບນິເວດທີ່ເຕີບໂຕ",
    "t51": "ພັດທະນາເຄື່ອງມື ແລະແອັບພລິເຄຊັນສຳລັບຜູ້ເຂົ້າຮ່ວມ.",
    "t52": "ພາບລວມທິດທາງການພັດທະນາ. ຂັ້ນຕອນ ແລະວັນທີດຳເນີນງານຈະຖືກເຜີຍແຜ່ເມື່ອແຜນການພັດທະນາໄດ້ຮັບການຢືນຢັນ.",
    "t53": "ອະນາຄົດຖືກສ້າງຂຶ້ນ<br><em>ຮ່ວມກັນ</em>",
