    "t11": "ဘလောက်ချိန်းပေါ်ရှိ လုပ်ငန်းများကို ညှိနှိုင်းဆောင်ရွက်ရန် ချဉ်းကပ်မှုအသစ်။ PoCol အကြောင်း လေ့လာ၍ ပူးပေါင်းဆောင်ရွက်မှုကို ရှာဖွေပြီး ဤခရီးစဉ်တွင် ပါဝင်လိုက်ပါ။",
