    "t18": "ချိတ်ဆက်နေသည်…",
    "t19": "နောက်ဆုံးဘလောက်",
    "t20": "ဆိုင်းငံ့ထားသော ငွေလွှဲမှုများ",
    "t21": "ပျမ်းမျှ ဘလောက်ဖန်တီးချိန်",
    "t22": "သတ်မှတ်ချက်ပြည့်မီသော မိုင်းတူးဖော်သူများ",
    "t23": "PoCol Explorer မှ တိုက်ရိုက်ဒေတာ · ၁၅ စက္ကန့်တိုင်း အပ်ဒိတ်လုပ်သည်။",
    "t24": "POCOL နောက်ကွယ်ရှိ အယူအဆ",
    "t25": "ညှိနှိုင်းထားသော လုပ်ငန်း။<br>မျှဝေထားသော ဖြစ်နိုင်ခြေများ။",
    "t26": "Proof of Collaboration သည် ညှိနှိုင်းဆောင်ရွက်မှုကို အယူအဆ၏ ဗဟိုချက်တွင် ထားရှိသည်။ ပါဝင်သူများသည် ကွန်ရက်တစ်ခုအတွင်း မည်သို့ အတူတကွ လုပ်ဆောင်နိုင်မည်နည်း?",
    "t27": "ပူးပေါင်းဆောင်ရွက်ရန် ရည်ရွယ်၍ ဒီဇိုင်းဆွဲထားသည်",
    "t28": "ပါဝင်သူများအကြား လုပ်ငန်းအပိုင်းအခြားများကို ညှိနှိုင်းခြင်းသည် PoCol ၏ ချဉ်းကပ်မှုအစဖြစ်သည်။",
    "t29": "ဖြစ်ပျက်နေသည်များကို ကြည့်ရှုပါ",
    "t30": "ကွန်ရက်ကြည့်ရှုကိရိယာကို ချိတ်ဆက်ပြီးပါက ဘလောက်များ၊ ငွေလွှဲမှတ်တမ်းများနှင့် ကွန်ရက်လှုပ်ရှားမှုကို လေ့လာနိုင်မည့် နေရာ။",
    "t31": "တည်ဆောက်ရန် နေရာ",
    "t32": "ပရိုတိုကောကို နားလည်ခြင်းမှ စတင်၍ ကိရိယာများ ရရှိလာသည်နှင့်အမျှ စနစ်ပေါင်းစည်းမှုများနှင့် အက်ပ်များအထိ ဆက်လက်သွားမည့် ဆော့ဖ်ဝဲဖန်တီးသူ၏ ခရီးစဉ်။",
    "t33": "ကွန်ရက်ထဲရှိ သင့်နေရာ",
    "t34": "သင့်လမ်းကြောင်းကို ရွေးချယ်ပါ။<br><em>နောက်တစ်လှမ်းကို လှမ်းပါ။</em>",
    "t35": "ပိုက်ဆံအိတ်ကို အသုံးပြုမည်",
    "t36": "PoCol ဂေဟစနစ်သို့ သင်ဝင်ရောက်မည့် လမ်းပေါက်",
    "t37": "ကွန်ရက်တွင် ပါဝင်မည်",
    "t38": "နုတ်များနှင့် မိုင်းတူးဖော်မှုအကြောင်း လေ့လာပါ",
    "t39": "PoCol နှင့်အတူ တည်ဆောက်ပါ",
    "t40": "ပရိုတိုကောမှ စတင်ပါ",
    "t41": "ရှေ့ဆက်မည့် ခရီးစဉ်",
    "t42": "ဆက်လက်ဖွံ့ဖြိုးနေသော အယူအဆ။<br>တစ်ဆင့်ပြီးတစ်ဆင့်။",
    "t43": "အခြေခံ",
    "t44": "ပရိုတိုကောနှင့် သုတေသန",
    "t45": "ပူးပေါင်းဆောင်ရွက်မှု ယန္တရားနှင့် ၎င်း၏ သုတေသနအခြေခံများ။",
    "t46": "အတွေ့အကြုံ",
    "t47": "ကွန်ရက်နှင့် ကိရိယာများ",
    "t48": "ပိုက်ဆံအိတ်များ၊ ပါဝင်ဆောင်ရွက်မှုနှင့် လှုပ်ရှားမှုများကို လေ့လာခြင်း။",
    "t49": "အနာဂတ်အလားအလာ",
    "t50": "ကြီးထွားနေသော ဂေဟစနစ်",
    "t51": "ပါဝင်သူများအတွက် ကိရိယာများနှင့် အက်ပ်များ ဖန်တီးခြင်း။",
    "t52": "ဦးတည်ချက် အနှစ်ချုပ်။ ဖွံ့ဖြိုးရေးအစီအစဉ်ကို အတည်ပြုပြီးပါက အကောင်အထည်ဖော်မည့် အဆင့်များနှင့် ရက်စွဲများကို ထုတ်ပြန်ပါမည်။",
    "t53": "အနာဂတ်ကို တည်ဆောက်နေသည်။<br><em>အတူတကွ။</em>",
    "t54": "ခရီးစဉ်၏ အစိတ်အပိုင်းတစ်ခု ဖြစ်လာပါ ↗",
